-- Generated source references; not native quest records.
local addon = WordHunterWoW_Addon
local compat = addon and addon.Compat
local flavor = compat and compat.GameFlavor and compat.GameFlavor()
if not (flavor == "retail") then return end
local pack = WordHunterWoW_QuestSources and WordHunterWoW_QuestSources["multilanguage-retail"]
if not pack then return end
pack.loaded = true
local quests = pack.locales.enUS

quests[91967] = { id = 91967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Know This Evil?", description = "Champion, we have a bit of a delicate situation.\n \nThe Vanguard of the Light has just informed me they have taken Magister Umbric into custody. Apparently he was trying to get close to the Sunwell.\n\nI do not have to tell you that tensions are high between my city and the Vanguard. We need Umbric to continue his research if we are to have a chance at contending with the Voidstorm.\n\nI want you to represent me in negotiating Umbric's release. Whether we like him or not, we need him.", progress = "Umbric is necessary. So is the Vanguard. \n\nI have a lot of necessary and unsavory elements to deal with these days, but I will do so if it means my people are safe.", completion = "Thank you for your intercession. While I prize myself on doing what is necessary for Silvermoon and the Sunwell, I have a feeling my own patience would have worn thin and I would have said something that all of us would have regretted.", objectives = "Negotiate with the Vanguard of the Light for Magister Umbric's release.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91968] = { id = 91968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome Home", description = "What a mess! Perhaps the previous owners left in a hurry. Best tidy up!\n\nThe items removed will be sent to the house chest. They can always be placed down again, if cobwebs are your thing.", objectives = "Pick up objects in your house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91969] = { id = 91969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time to Decorate", description = "Now that we've got this place tidied up, let's decorate!\n\nThe community has chipped in with donations to make sure you have plenty of options to work with.\n\nLet's have a look!", objectives = "Decorate your home.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91970] = { id = 91970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Gelatonius", description = "Are you ready to test yourself against a true foe? In the center of the Gloom Mire is Gelatonius, a fungal giant of enormous proportions. \n\nKill him, if you think you can. I'm willing to be impressed, and to pay handsomely for this task.", completion = "You return in one piece? Not bad, outsider. Not bad.", objectives = "Kill Gelatonius in the Gloom Mire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91971] = { id = 91971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hitting the Hammer", description = "The Twilight Hammer is dirtying up the ruins of Zeb'tala. Clean up the area and bring back some of their personal tokens. One never knows what curiosities may appeal to those vying for relevancy.\n\nThose mindless cultists may stomp around and act tough, but you will make quick work of them.", sourceObjective = "Bring back 6 Twilight Tokens.", progress = "Have you found anything useful?", completion = "You have successfully blunted those Twilight tools. Whether or not we will have any takers for this odd assortment of tokens is yet to be determined.\n\nThere is, however, no accounting for taste.", sourceObjectiveStatus = "unverified-source-field" }
quests[91972] = { id = 91972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hold the Watch", completion = "An uneventful watch is more rewarding than an empty conversation.\n\nThe Blood Knights appreciate your service.", objectives = "Check in with Bloodguard Nelric at the Thalassian Pass and hold the watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91973] = { id = 91973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naga Blades", description = "It seems the locals currently find great appeal in naga blades--the brinier the better. On our southwestern shore, you will find the Daggerspine naga.\n\nThey have these grungy, barnacle-encrusted scimitars that would perfectly fit the bill.\n\nGo grab a few of those. They could have value in some of our upcoming discussions.", sourceObjective = "Collect 7 Naga Scimitars.", progress = "Were you able to procure some blades?", completion = "Excellent work! These will do nicely.\n\nBetween us, my personal preference leans toward the colorful seashells. Maybe that is because my sword is more than an adornment.", sourceObjectiveStatus = "unverified-source-field" }
quests[91974] = { id = 91974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunfire to the Blade", description = "I guess there is one benefit to being part of the courtly intrigue: one does hear things. We have this concoction of sunfire infused with the holy energy of the Blood Knights, courtesy of the court alchemists.\n\nTake this down to the Sanctum of the Moon and test it on the Twilight intruders. I look forward to hearing the results in detail.", completion = "Anar'anel belore! You love to hear it. This news is sure to warm a few hearts for our cause.", objectives = "Kill 10 Twilight intruders at the Sanctum of the Moon with Holy Sunfire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91975] = { id = 91975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Our Wood", sourceObjective = "Collect 5 Harvested Lightwood.", progress = "Did you gather the lightwood?", completion = "Your task is done. These will prove useful.\n\nDo not let on that the Blood Knights got first pick.", sourceObjectiveStatus = "unverified-source-field" }
quests[91976] = { id = 91976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightbloom Dimmed", description = "All of this small talk makes my ears twitch. I would be so much more useful doing field work. For now, you get to do the fun part.\n\nThe creatures within the Lightbloom are getting a bit dense. I need you to get out there and lower the volume.\n\nI am sure you'll run into many options while you are out there. Take a whack at a few for me.", completion = "You have performed well. Silvermoon appreciates your service.\n\nI would have happily swapped places with you, but we all have our assignments.", objectives = "Kill Lightbloom creatures.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91977] = { id = 91977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Less Lawless", description = "The Tideborne are always running just over the legal line. They are an annoyance at best, but will push boundaries when given too much rope.\n\nThe ones in Sunsail Anchorage made the mistake of ripping off some nobles not too long ago. Maybe go smack them around a bit--remind them to respect their betters.", completion = "Ah, that must have been such fun! My bar may be lower today, after the engrossing discourse on the harvesting cycle of the basic peacebloom.\n\nApologies. Know your service is appreciated.", objectives = "Chastise 8 Tideborne.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91978] = { id = 91978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taxing the Tideborne", description = "Have you ever noticed, that sometimes there is benefit in letting someone think they are getting away with something? The Tideborne will continue to smuggle in plain sight, feeling clever at the taxes they're avoiding paying to Silvermoon.\n\nThis does add up, though, over time. When you have a moment, please head down to the harbor and relieve them of some of their back taxes.", sourceObjective = "Collect 50 Tideborne Dubloons.", progress = "Is it still stealing when stolen from thieves?", completion = "One must appreciate the special jingle of a heavy sack of purloined coins.\n\nExcellent work, my friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[91979] = { id = 91979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chop It Down", description = "We received word there's a creature from Lightbloom Ath'Ran making trouble on the western coast. It has caused a bit of drama.\n\nHead over and resolve the issue.", completion = "Good work. I'm sure that will make for some excellent kindling.", objectives = "Kill the Rampaging Ent near Lightbloom Ath'Ran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91980] = { id = 91980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Hellebora's Thorn", description = "See that huge creature over that way? That's Hellebora. She's set herself up too close to the road and we're concerned she's going to wander out of the mire and become even more of a threat. \n\nDeal with her, if you can, and bring me back one of her thorns as proof of your hunt.", progress = "Hurry up and put Hellebora down before she wanders out of the mire.", completion = "You return with her thorn? Ah yes, a fine trophy. Well done.", objectives = "Kill Hellabora.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91981] = { id = 91981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Poison and to Heal" }
quests[91982] = { id = 91982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Toadshade's Petals", description = "The three-headed hydra, Hellabora, has been causing havoc in the lower end of Gloom Mire.\n\nGive her a good pruning and bring me back her petals as proof.", progress = "Less talking, more pruning. Go get those petals.", completion = "You've the petals? Let's take a look. Yes, these are from that hydra. Good work.", objectives = "Collect petals from Toadshade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91983] = { id = 91983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lovely Plumage", description = "The beautiful members of the Silvermoon Court do so love their colorful embellishments.\n\nFor this, we can stock up while doing a good deed! Head over to Thuron's Livery and pick up some of the brightly colored feathers shed from the hawkstriders in training.\n\nVaelith gets clean up service and we get the lovely plumage.", progress = "Did you find loads of feathers?", completion = "You are so good at this!\n\nOne of these days, we should pile these feathers up and let everyone jump in them. I think you would be surprised how many proper lords and ladies would gleefully participate.\n\nFor now, we will explore feathery accents.", objectives = "Collect 8 Bright Feathers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91984] = { id = 91984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sungrub Silk", sourceObjective = "Gather 3 Sunsilk.", progress = "Oh, did you get all of the silk?", completion = "Perfect! I have to confess, it will be hard to give some of this up.\n\nI must remember, I have a job to do here. It can't all be fun and games.\n\nYour work is appreciated.", sourceObjectiveStatus = "unverified-source-field" }
quests[91985] = { id = 91985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windrunner Memorabilia", description = "The nobles do so love the unusual. Take a look around Windrunner Village. There are sure to be some interesting mementos still tucked away there.\n\nI will find an advantageous home for the pieces you bring back.", sourceObjective = "Collect 5 Windrunner Memorabilia.", progress = "Did you find anything interesting?", completion = "I asked for unusual and you delivered! A couple of these seem a bit... suspect.\n\nI'm sure it will be fine. What could go wrong with items of mysterious origin?", sourceObjectiveStatus = "unverified-source-field" }
quests[91986] = { id = 91986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put a Little Snap in Their Step", description = "Those naga are, as ever, being a beachfront nuisance. Do they not understand that is a prime location?\n\nWe may not be able to reliably drive them off, but a little mischief would not be untoward.\n\nI found this tune that drives the snapdragons mad. They will just attack whoever is nearby. Take this and give it a shot!", completion = "I feel bad for the snapdragons, but I can't help but laugh at the look of surprise on their face when their little buddies pounce on them.\n\nThank you for making the day a little more entertaining.", objectives = "Drive 8 Daggerspine Snapdragons mad with a tune.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91987] = { id = 91987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Potted Lashers", progress = "Any problems with the harvest?", completion = "The results of sharing these with the Silvermoon elite could range from passably amusing to disastrous.\n\nEither way, I look forward to seeing the results of their gardening efforts.", objectives = "Collect 8 Lightblooming Bulbs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91988] = { id = 91988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brightwing Conservation", description = "The conservators at Brightwing Estate have a mischievous young dragonhawk named Cerul that likes to run away whenever their backs are turned. He doesn't go far, but it has become a game for him to get them to chase him.\n\nTake this delicious treat with you and use it to lure him back home.", completion = "It makes everyone happy to have all the creatures home at Brightwing. Having a peaceful place to enjoy the coast is a benefit to all.\n\nThank you for letting Cerul enjoy a little play time!", objectives = "Lure Cerul back to his home in Brightwing Estate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91989] = { id = 91989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghostland Peppers", description = "The delicate blue ghostland peppers may not look like much, but they have a mean burn. Many nobles won't admit it, but they are quite popular in the noble games of \"Truth or Challenge.\"\n\nPlease procure a few for me. I like to watch them sweat.", sourceObjective = "Collect 12 Ghostland Peppers.", progress = "How goes the harvest?", completion = "Joy! These will bring much excitement, and some chagrin, to the court.\n\nMany thanks! Oh, and {name}... be sure to cleanse your hands before you rub your eyes--or worse. I learned that the hard way.", sourceObjectiveStatus = "unverified-source-field" }
quests[91990] = { id = 91990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunset to Sea", description = "Naga have set up camp on the Sunset Strand. The sunset slugs that called it home are distraught and seem unsure what to do. This little tune will remind them of their home.\n\nGo inspire them to seek the freedom of the open sea.", sourceObjective = "Send 7 Sunset Slugs back to the sea.", completion = "Best of luck to our little nudibranchian friends! Yes, I made that word up, but is it not accurate?\n\nThank you for helping them seek out more pleasant waters.", sourceObjectiveStatus = "unverified-source-field" }
quests[91991] = { id = 91991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Errand", description = "When conversations get tense, it can be challenging to keep words flowing in a productive way. At times like these, I find a little social lubrication is in order.\n\nSwing over to Goldenmist Village and pick up a cask of Vintner's Golden. It's proven to have a euphoric side effect that can be quite helpful.", sourceObjective = "Collect a Cask of Vintner's Golden.", progress = "Did you find the cask?", completion = "Perfect! This is just what the court ordered.", sourceObjectiveStatus = "unverified-source-field" }
quests[91992] = { id = 91992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Has the Wine Gone?", description = "I entrusted one of my apprentices with the delivery of several cases of particularly expensive wine. He was to bring them here from my private storage, but he has not yet arrived.\n\nI should hate to ask you to retrieve him, but I cannot stress enough how expensive those bottles are.\n\nPlease see if you can locate him and my delivery. He should have been traveling from the north to arrive here.", sourceObjective = "Locate the Magister's lost apprentice in Eversong Woods and figure out what happened to the wine shipment.", progress = "I dearly hope my apprentice has a colorful excuse for his tardiness.", completion = "The wine attacked you both, you say? Ah yes, I suppose the mana in that particular vintage is prone to sedimentation.\n\nI am pleased most of it was recoverable.", sourceObjectiveStatus = "unverified-source-field" }
quests[91993] = { id = 91993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diminutive Demand", description = "Keeping preciously small animals as pets is a popular pastime among the nobility. The more unconventional the animal, often obtained through magic, the more of a conversation piece it is.\n\nI have enchanted this wand with the appropriate shrinking spell. Use it on some of the colorful toads out near the ponds and bring them back here. The nobles will find them delightful.\n\nNaturally, the toads may not take kindly to the enchantment. But I trust you can handle that, should it occur.", completion = "Oh, they are positively precious, are they not?\n\nI imagine we will see quite a few miniscule toads in handbags this coming season.", objectives = "Using the Wand of Diminutive Proportions, shrink and capture 4 Gloombelly Toads near Stillwhisper Pond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91994] = { id = 91994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pyrepetal Purposes", description = "Lord Saltheril, that old lynx, has put me in a bit of a bind.\n\nHe has requested a grand fireworks display to accompany tonight's dinner service, but we are dreadfully low on pyrepetal dust. It is an herb native to Eversong, highly flammable and quite dazzling when set aflame by pyromancy.\n\nCould you help us replenish our stores? We mostly harvest it from the woods near Scintilas Falls.", sourceObjective = "Gather 5 Eversong Pyrepetals near Scintilas Falls.", progress = "Do be careful to keep the pyrepetals away from open flame.", completion = "Wonderful. This quantity should be sufficient for a lovely round of fireworks.", sourceObjectiveStatus = "unverified-source-field" }
quests[91995] = { id = 91995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Horrible Magic", description = "Have you seen the encampments the naga have been constructing along our coast? Dreadful business.\n\nNot only do they menace our ships and disrupt our trade routes, but they might pose a real threat to Eversong's inland settlements if allowed to continue operations unchecked.\n\nTheir arcanists are particularly dangerous. Dispose of them and our guests will be in your debt.", sourceObjective = "Slay 4 Daggerspine Infusers near Daggerspine Point.", progress = "I trust this task is within your skill set.", completion = "Marvelous. I am certain our guests would have preferred to see the battle themselves, but tales of your heroism will do nicely.", sourceObjectiveStatus = "unverified-source-field" }
quests[91996] = { id = 91996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fit for a Magister", description = "Battle prowess and magical skill are important, of course, but one cannot deny the power of appearances. A well-dressed army instills far more faith than one bedecked in rags.\n\nFortunately, a fine set of robes can be both flattering and functional. The mana silk produced at the North Sanctum can be woven into robes that deepen and intensify our magical reserves.\n\nBe a dear and gather some for us, would you? My wardrobe could use a seasonal refreshment.", sourceObjective = "Gather 5 Iridescent Mana Silk and weave it into a Bolt of Mana Silk Cloth at the North Sanctum.", progress = "Do be careful around the mana wyrms. I understand they can be aggressive after harvesting.", completion = "Mana silk has a beautiful sheen, does it not?\n\nThe Magisters will be looking spectacular throughout the soiree.", sourceObjectiveStatus = "unverified-source-field" }
quests[91997] = { id = 91997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power Clean", description = "The festivities have been wonderfully entertaining, which means the nobles have been leaving a bit of a mess around the estate. Lord Saltheril's servants have been keeping up with the cleaning, but the Magisters could lend a hand.\n\nEnchanting a few brooms to sweep the pavilion should be an easy but impressive feat.\n\nI was informed that an arcanist was employing the same tactic over at Farstrider Hold. Go retrieve some of his brooms and I will have them re-enchanted here.", sourceObjective = "Forcefully deactivate and collect 5 Inanimate Brooms at Farstrider Hold.", progress = "Technically any broom would do, but the magic is easier to weave if the object has already been primed to receive the enchantment.", completion = "We will have the estate shining in no time.", sourceObjectiveStatus = "unverified-source-field" }
quests[91998] = { id = 91998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Muckmire's Choking Vines", description = "Deep within the swamp is a creature of mud, leaves, and rage. His vines choke the life out of any who come near, and this dangerous creature cannot be allowed to live.\n\nDefeat Muckmire and bring me back his vines as proof of the deed.", progress = "Be careful Muckmire doesn't drag you into the mud with him.", completion = "You look properly covered in mud and grime. Have you done it? \n\nAh yes, these are his vines. Well done.", objectives = "Collect the choking vines of Muckmire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91999] = { id = 91999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bit of Bloodthistle", description = "You know, I bring Saltheril a lot of \"imported\" wine, but one of the first things I started supplying him with was bloodthistle. It's an herb that only grows around Eversong. It's got a smooth bite to it, sort of like mana. Nice and classy. His parties really go through the stuff.\n\nI took a look and I don't think he has enough to last this whole thing. We should get some more.\n\nThe best stuff grows over by the West Sanctum. Grab as much as you can carry. Trust me--it'll go fast.", sourceObjective = "Gather 5 Fragrant Bloodthistle near the West Sanctum.", progress = "Trust me. I know how to keep nobles happy.", completion = "Nice haul. You've got a good eye for this stuff.\n\nIf you're ever looking for work after this thing's over, let me know.", sourceObjectiveStatus = "unverified-source-field" }
quests[92000] = { id = 92000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring the Ruckus", description = "This place is pretty fun so far, despite all the dry political talk. I know Saltheril is trying to get the nobles to buy up war bonds, but we could really use some more energy in here. If the nobles are all asleep, no one's buying anything.\n\nTell you what. Go invite some of my friends. They hang out under the bridge right outside of Silvermoon's gates.\n\nIf anyone can bring some energy to the soiree, it's us.", completion = "The energy's high, the drinks are flowing, and people are having a good time!\n\nThat's how you start making deals.", objectives = "Pass along Vyrin's invitation to 6 of his \"trader\" friends near the Path of Dawn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92001] = { id = 92001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Smuggler to Another", description = "The whole point of this deal is showing the nobles what we bring to the table, both for Silvermoon and for them personally.\n\nThese other groups bring strength, power, and really nice armor. What we bring is resources: getting the sin'dorei what they need, when they need it, with no questions asked.\n\nI heard some folks over at Sunsail Anchorage have been trying out the same business, but they're putting gold in the wrong pockets. Swipe their stock and bring it here.", sourceObjective = "Collect 5 Smuggled Goods around Sunsail Anchorage.", progress = "I don't mind competitors, but I don't like the deals those smugglers are making.", completion = "If there's anything good in these crates, we'll get it on the market.", sourceObjectiveStatus = "unverified-source-field" }
quests[92002] = { id = 92002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous Showpieces", description = "You'd be surprised at the money you can make off of weapons. No, not the kind you're meant to use--the kind you stick up on the wall and have conversations about.\n\nUsually those weapons are expensive, or dangerous, or otherwise hard to get your hands on. The more rare and exclusive, the better.\n\nThe weapons those Twilight cultists are carrying around should sell pretty well, especially to buyers with edgier tastes. If you happen to come across any, I'll gladly take them off your hands.", progress = "If it has some blood on it, that's actually better.", completion = "Nice work. Eversong is safer because of your heroism, and I get to pocket a little more gold. I'd call that a win-win.", objectives = "Collect 6 pieces of Twilight Weaponry from cultists at the Sanctum of the Moon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92003] = { id = 92003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artisanal Replicas", description = "Don't let the austere demeanor fool you. Nobles are just as susceptible to flashy party favors as the rest of us.\n\nI had my people bring over a batch of Felo'melorn replicas. They look great on display, and even better--they're enchanted. Swing them around and they leave a trail of fire.\n\nI haven't sold an enchanted batch before, so I'd like to do some testing before I hand them out. Saltheril wouldn't be too happy if I burned a guest to a crisp.\n\nWanna take one of the replicas for a test run?", sourceObjective = "Test the fiery capabilities of the Felo'melorn Replica on 5 creatures near Lightbloom Ath'Ran.", progress = "I recommend trying it out on something not flammable.\n\nOr extremely flammable. Up to you.", completion = "I told you they were flashy!\n\nSounds like the enchantment could get tuned down a little bit, but where's the fun in that?", sourceObjectiveStatus = "unverified-source-field" }
quests[92004] = { id = 92004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shady Dealings", description = "I feel like I just got here and I'm already fresh out of half the poisons I brought.\n\nWhat? Don't look at me like that. Nobles are some of my top customers for poisons. Quieter than magic and cleaner than blades.\n\nI need to restock. The frogs way down in the south produce a poisonous slime that I can bottle without much fuss. Bring some of it to me and I'll get you a cut of the earnings.", sourceObjective = "Collect 6 Poisonous Frog Secretions from frogs near the Amani Pass.", progress = "Were you able to find any of those frogs?", completion = "Excellent. That's enough to restock what I've sold and then some.\n\nOh, by the way, you probably want to wash your hands. Maybe a few times.", sourceObjectiveStatus = "unverified-source-field" }
quests[92005] = { id = 92005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Throw the Dice", description = "We've been making friends with some of the guests by teaching them how to play dice. It's a nice way to draw people out of the crowd and get them in a quieter space where you can talk privately.\n\nI wasn't expecting so much interest, to be honest. We're running out of dice sets.\n\nI can carve some more, but I'll need materials. Usually teeth or bone are good picks. Actually, the fangs from those naga along the coast would be perfect. Now that's a conversation starter!", progress = "Any luck finding some of those fangs?", completion = "Oh, that smell is... very fishy. Definitely going to let these dry out for a while.\n\nYour exceptionally efficient help is appreciated, {name}.", objectives = "Collect 12 Naga Fangs from naga near the Sunset Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92006] = { id = 92006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Need a Refill", description = "I talked to some of the servants earlier and it sounds like the casks are running low. That's a recipe for disaster at an event like this.\n\nFortunately, I've got a lot of contacts across Eversong who can help us restock.\n\nI need to stay here and play politics, but could you head over to Tranquillien and grab a few bottles? I'll give you a list.", progress = "Trust me. Everything on that list is fantastic.", completion = "Nice work. I'll see about getting those casks refilled, but these bottles should keep everyone happy in the meantime.", objectives = "Purchase a case of Bloodthistle Brandy, Mana Burner, and Sun-Kissed Tranquilla from vendors in Tranquillien.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92007] = { id = 92007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begged, Borrowed, or Stolen", description = "The oldest trick in the book is to create a problem on purpose, solve it yourself, and look like the hero.\n\nOne of the nobles just got word that some prized valuable was stolen from their estate while they were occupied here. It just so happens I might have put one of their servants up to it.\n\nGo talk to a man named Seridis over at the livery. He'll hand over the valuable to you, then you'll come back here and pretend you valiantly subdued the thief and retrieved the item.\n\nEveryone's happy.", progress = "Making friends with the servants in noble households opens up a lot of doors. Sometimes literally.", completion = "Look at that. Everyone comes out a winner!\n\nThe noble gets his valuable back unscathed, Seridis gets paid handsomely, and you and I look brave and capable in front of the soiree.", objectives = "Speak to Seridis at Thuron's Livery, then retrieve the stolen item.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92010] = { id = 92010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Slewstalk's Stalks", description = "Not far from here, Slewstalk lurks in the shallows. This creature has developed a taste for flesh and bones, and it won't be long until she wanders out of the Mire in search for warmer blooded prey.\n\nTake her out and bring me her luminescent stalks. They'll serve as proof and also make a fine centerpiece for an evening table.", progress = "Try to take Slewstalk down before she can get those long grippers of hers around you.", completion = "Ah, you return. And with glowing stalks to adorn my dinner table. Well done.", objectives = "Collect luminecent stalks from Slewstalk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92012] = { id = 92012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Gorebarb's Pincers", description = "Gorebarb is a creature quite unlike most others who make Harandar their home. He's incredibly violent and his kind is not seen here very often. \n\nLet's see less of him. Kill him and bring me his pincers as proof of the deed.", progress = "Take care that Gorebarb doesn't catch you with those pincers. I imagine his breath isn't pleasant at all.", completion = "Well, well. You managed to take down Gorebarb and retrieve the pincers? Ah, of course I never doubted you would.", objectives = "Collect Gorebarb's Pincers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92013] = { id = 92013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Dionaea's Thorntusks", description = "Many thornmaws make the mire their home, but none as are vicious as Dionaea. Unlike the others, she kills merely for the joy of it, and her gluttony threatens the delicate balance of the wildlife in this area. \n\nTake her out and restore the equilibrium. Bring me back her thorntusks as proof of the deed.", progress = "Dionaea hunts for the thrill of it. She seems to be unable to satiate her hunger. Have you handled her yet?", completion = "You bring me the thorntusks? Excellent. May balance return to the Mire.", objectives = "Collect Dionaea's thorntusks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92018] = { id = 92018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "x.x Testing (YGR)" }
quests[92021] = { id = 92021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Graveblossom Gardening", description = "My colleague Amalthea has taken ill. She requires a specialized poultice of sorts in order to ease the symptoms. I would forage for the plants myself, but the local fauna have grown so testy as of late!\n\nWhile you are out and about, could you gather some graveblossoms for me? I'd happily make it worth your while.", progress = "Oh, come now. While we stand here and chat about the weather, my associate continues to suffer under the travails of her malady! Get on with it.\n\nIt's gloomy, by the way. The weather. As usual.", completion = "There you have it! Eight flowers. Simple enough, no? Now, I just need a few more things...\n\nWhat? I didn't mention that there would be a shopping list? Oh, bother. Well, nothing to it but to do it now, hrm? You don't seem the type to leave things half-handled.", objectives = "Gather 8 Pristine Graveblossoms for Talandra Dawnsprite at Windrunner Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92022] = { id = 92022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Venomous Vocation", description = "My poultice requires venom samples from the local giant bat populations. Please retrieve some of those, as well. Six common vials' worth should do.\n\nDon't give me that look. They're bats. There are mad Light-plant-things to the east and a storm of voidwalkers swirling over our heads. Don't you dare give me guff about the dangers of big, fluffy bats. Now shoo. My colleague is depending on your prompt and efficient aid.", progress = "Strictly speaking, a stronger venom would have a more ample effect. But we're living in strenuous times. This Void hooplah has my usual supply lines at Sunsail completely occupied. We'll have to make do with mournbat venom. Now go.", completion = "There we are. See? I knew I could rely on you. We've only a few steps left to manage.", objectives = "Collect six vials of Potent Mournbat Venom from mournbats outside of Windrunner Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92023] = { id = 92023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suspicious Sundries", description = "Forgive me for my failure to provide specifics, traveler. The mournbat venom and the graveblossoms were only the first of the reagents I require for my associate's medication.\n\nLuckily, the final few things I require can all be easily obtained in Goldenmist Village to the north. Be a dear and fetch these last few things for me, won't you? With these, my toil will be nearly complete.", progress = "Eugh. Why do I smell grave soil on you?", completion = "That's an interesting bag of goods you're carrying there, friend. I don't suppose you're shopping on behalf of the \"apothecary\" in Windrunner Village?\n\nYou may wish to reconsider this course, if you value your well-being.", objectives = "Fetch a Vial of Quicksilver, a Flask of Dragon's Blood, and a Bottle of Magister's Reserve from the vendors at Goldenmist Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92024] = { id = 92024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "House Call", description = "That woman, that \"apothecary,\" has snared you in one of her schemes.\n\nI'd be careful around her, {class}. Rumors travel like wildfire in Eversong. And while I would never disparage a fellow artisan of Eversong without cause, I have heard enough rumors to know that your apothecary deals in more than simple herbs.\n\nTake your wine and your reagents, I suppose. But before you pass them off to your patroness, I'd recommend doing some digging--lest you find yourself wrapped up in something you come to regret.", completion = "<Your findings leave little to the imagination. Whatever official enterprises Talandra purports to pursue, her personal affects betray a more sinister profession.>", objectives = "Investigate Talandra's home in Windrunner Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92025] = { id = 92025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flowers for Amalthea", description = "<The final pages of the tome detail a meeting place. Whatever Talandra Dawnsprite intends to do, she means to do it amidst the ghosts of Windrunner Spire.\n\nThe time for Talandra's ritual grows nigh.>", progress = "<Time is of the essence. Talandra's ritual approaches.>", completion = "Goodness! That was nearly quite the misunderstanding. I am glad you stayed your weapons long enough to hear me out.\n\nThe Scourge took much from the sin'dorei. For some, like Amalthea, it took everything and more.\n\nNeedless to say, my studies don't get me invited to many parties. But they allow me, from time to time, to ease Amalthea's torment. To that end, I would bear any indignity.", objectives = "Confront Talandra Dawnsprite at Windrunner Spire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92028] = { id = 92028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pardon the Interruption", description = "{name}! Glad to see you. The defenders in the fortress could use your help.\n\nOne of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on.\n\nShe needs the help of someone who can properly interrupt the robot's attacks so it can be repaired.\n\nDo you have a moment to help?", progress = "Some help! Hopefully you can find a way to interrupt this bot's abilities.", completion = "Great work! Now I should have time to fix whatever bug actually caused this in the first place.\n\nMaybe I can just say it's a feature and call it a day!", objectives = "Activate Fightbot 11.2.7, then interrupt its abilities 3 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92030] = { id = 92030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Tradition", completion = "Ah, {name}... you have traveled far, but returned. You have reminded all who live here that the Spirit Festival is not just for the elemental spirits, but the spirits of all {race} who call this place home... even if they leave for a time. \n\nIn thanks, our tailors have crafted these for you. The maker's design celebrates your adventures, but also honors your origins... just as you have today.\n\nMaster Shang Xi would be so, so proud.\n\n\n\nTo you, my friend. To home.", objectives = "Meet Chon Po in Wu-Song Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92031] = { id = 92031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the Vandals", description = "<The Manaforge Vandals at Shadow Point are eager to see the Shadowguard and their allies removed from Manaforge Omega. It's probably a good time to pay them a visit.>", completion = "Hero! Your reputation for toppling tyrants precedes you. Let's see about adding one more to that list.", objectives = "Report to Zo'turu at Shadow Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92034] = { id = 92034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thorm'belan" }
quests[92061] = { id = 92061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rising Storm", description = "That was an entropic wave. We felt them just before Xal'atath launched her assault on the Sunwell. \n\nChampion, you move faster than my best messengers. I need you to check in with the Vanguard commanders and see if their defenses will hold against this latest assault by Xal'atath's Devouring Host.", progress = "Tensions are high.", completion = "Well done. That Voidstorm is evoking fear and terror in everyone who sees it, myself included. \n\nBut I chose this life of standing up to evil and spitting in its face. Sadly not everyone had the luxury of that being a choice.", objectives = "De-escalate rising tensions in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92062] = { id = 92062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tending the Roots" }
quests[92063] = { id = 92063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: A Hunter's Regret" }
quests[92078] = { id = 92078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Recipe!", objectives = "You're back already! I believe I've found a use for the Manaforged Instruments you may have found within Araz's possession. Each are pieces of machinery that, if extracted properly, would yield a unique energy signal not dissimilar to the magic used to bind Ethereals. If you or anyone you know are particularly well-versed in Enchantmenting or Inscription, take these! They may hold secrets, or at the very least a novel experience for you. Good luck!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92082] = { id = 92082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Someone Like Me", objectives = "Hero... far be it from me to question your methods in taking down the All-Devouring, but I've noticed your snooping while inside Omega. Those cyphers you discovered are how we communicate with our contacts inside. I don't even know how you activated them - they were supposed to be heavily encrypted! Still... this is the kind of mischief I love to encourage. I'm not sure what use you'll get out of this disguise, but for all you've done for us, you've earned a treat. Just don't say you got it from me.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92084] = { id = 92084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halazzi's Guile", description = "Who are these people? Where did they come from?\n\nDid dey find their way here from Numazon? How? De mist keeps you from knowin' if you are comin' or goin'.\n\nAnd where is Halazzi?\n\nI need answers... now!", progress = "My vision is clearing, and so is my mind.", completion = "Like Akil'zon, Halazzi was watching. Waiting.\n\nHe never gave up on de Witherbark.", objectives = "Speak to Loa Speaker Tobui to discover how the Witherbark were rescued.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92085] = { id = 92085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claw Enforcement" }
