quests[92105] = { id = 92105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Papers, Please!" }
quests[92106] = { id = 92106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ignite the Skies: Northern Kalimdor", description = "Midsummer is the time to reflect and a time to tell stories by the bonfire.\n\nOne such story is the tale of the sun blossom ritual and how this offering to An'she first came to be.\n\nOur journey will take us through Northern Kalimdor, into territories beyond the lands of the shu'halo.\n\nIf you wish, take to the skies of Kalimdor and ignite the blossoms as I tell the tale.\n\nOur story begins in the Western Barrens...", sourceObjective = "Ignite the sun blossoms in the skies over Northern Kalimdor.", completion = "This important journey would soon become a yearly pilgrimage for the tribes of Central Kalimdor.\n\nAs the summer season approached, and the tribes began to gather near Stonetalon, a chosen few would journey to the highest peak and make offerings to the sun.\n\nAn'she was pleased by this act, and the offering of sun blossoms became pivotal to Midsummer celebration.", sourceObjectiveStatus = "unverified-source-field" }
