quests[92123] = { id = 92123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cragpine" }
quests[92136] = { id = 92136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infusion of Hope", description = "I hope my staff's light has been enough to uphold those at the Sunwell while we have sought these relics.\n\nTogether with those from Light's Hope, they should be a much more significant aid.\n\nLet us return there quickly.", completion = "Quickly, {name}. Let us get these distributed!", objectives = "Return the relics to Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92138] = { id = 92138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mobilize! Enlist! Recruit!" }
